import sys
sys.setrecursionlimit(10000)
MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n = data[0]
    pts = [(data[2*i+1], data[2*i+2]) for i in range(n)]
    # Sort by X; antichains in this two-dimensional order are decreasing
    # subsequences in Y. Enumerate them and deduplicate their survivor sets.
    pts.sort()
    ys = [p[1] for p in pts]
    # Each point's bit mask of points incomparable to it, including itself.
    masks = []
    for i, y in enumerate(ys):
        m = 0
        for j, z in enumerate(ys):
            if i == j or (j-i)*(z-y) < 0:
                m |= 1 << j
        masks.append(m)
    allmask = (1 << n) - 1
    answers = {allmask}
    def dfs(pos, last_y, curmask):
        for i in range(pos, n):
            if ys[i] < last_y:
                nxt = curmask & masks[i]
                answers.add(nxt)
                dfs(i+1, ys[i], nxt)
    dfs(0, n+1, allmask)
    print(len(answers) % MOD)

if __name__ == '__main__':
    main()

