import sys

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    N, M = data[0], data[1]
    inf = N + 1

    # For each position x and left endpoint l, store the minimum R
    # among constraints (L, R, x) with L >= l.
    min_r = [[inf] * (N + 2) for _ in range(N + 1)]
    p = 2
    for _ in range(M):
        L, R, X = data[p], data[p + 1], data[p + 2]
        p += 3
        if R < min_r[X][L]:
            min_r[X][L] = R

    for x in range(1, N + 1):
        row = min_r[x]
        for l in range(N, 0, -1):
            if row[l + 1] < row[l]:
                row[l] = row[l + 1]

    # q[l][r] is the satisfying count on [l,r], divided by its length!.
    q = [[0] * (N + 2) for _ in range(N + 2)]
    for i in range(1, N + 2):
        q[i][i - 1] = 1

    inv = [0] * (N + 1)
    if N >= 1:
        inv[1] = 1
    for i in range(2, N + 1):
        inv[i] = MOD - (MOD // i) * inv[MOD % i] % MOD

    for length in range(1, N + 1):
        inv_length = inv[length]
        for l in range(1, N - length + 2):
            r = l + length - 1
            total = 0
            for k in range(l, r + 1):
                # The maximum at k violates a condition exactly when some
                # constraint with X=k is wholly contained in [l,r].
                if min_r[k][l] <= r:
                    continue
                total += q[l][k - 1] * q[k + 1][r]
            q[l][r] = (total % MOD) * inv_length % MOD

    factorial = 1
    for i in range(1, N + 1):
        factorial = factorial * i % MOD
    print(q[1][N] * factorial % MOD)

if __name__ == '__main__':
    main()

