import sys

MOD = 998244353

def factorize(x):
    result = {}
    d = 2
    while d * d <= x:
        while x % d == 0:
            result[d] = result.get(d, 0) + 1
            x //= d
        d += 1
    if x > 1:
        result[x] = result.get(x, 0) + 1
    return result

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    factors = [factorize(x) for x in data[1:]]
    primes = set(p for f in factors for p in f)
    answer = 1

    for p in primes:
        steps = [f.get(p, 0) for f in factors]
        width = sum(steps)
        if width == 0:
            continue
        offset = width
        size = 2 * width + 1
        invp = pow(p, MOD - 2, MOD)
        weights = [pow(invp, c, MOD) for c in range(-width, width + 1)]
        cumulative_max_sums = []

        # For each upper bound on the walk maximum, sum weights of all
        # walks staying below that bound. Each visited cumulative position
        # contributes p^(-position).
        for bound in range(width + 1):
            dp = [0] * size
            dp[offset] = 1
            for step in steps:
                ndp = [0] * size
                if step == 0:
                    for idx, value in enumerate(dp):
                        if value:
                            ndp[idx] = value * weights[idx] % MOD
                else:
                    for idx, value in enumerate(dp):
                        if value:
                            pos = idx - offset
                            pos1 = pos + step
                            if pos1 <= bound:
                                j = pos1 + offset
                                ndp[j] = (ndp[j] + value * weights[j]) % MOD
                            pos2 = pos - step
                            if pos2 <= bound:
                                j = pos2 + offset
                                ndp[j] = (ndp[j] + value * weights[j]) % MOD
                dp = ndp
            cumulative_max_sums.append(sum(dp) % MOD)

        contribution = 0
        previous = 0
        for maximum, bounded_sum in enumerate(cumulative_max_sums):
            exact_max_sum = (bounded_sum - previous) % MOD
            previous = bounded_sum
            contribution = (contribution + exact_max_sum * pow(p, n * maximum, MOD)) % MOD
        answer = answer * contribution % MOD

    print(answer)

if __name__ == '__main__':
    main()

