import sys

MOD = 998244353
MAX_A = 100000


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    values = data[1:]

    # Smallest prime factor table.
    spf = list(range(MAX_A + 1))
    for p in range(2, 317):
        if spf[p] == p:
            for multiple in range(p * p, MAX_A + 1, p):
                if spf[multiple] == multiple:
                    spf[multiple] = p

    # Euler's totient function.
    phi = list(range(MAX_A + 1))
    for p in range(2, MAX_A + 1):
        if phi[p] == p:
            for multiple in range(p, MAX_A + 1, p):
                phi[multiple] -= phi[multiple] // p

    # weighted[d] = sum of 2^(i-1) over prior positions i with d | A_i.
    weighted = [0] * (MAX_A + 1)
    divisor_cache = {}
    answer = 0
    position_weight = 1
    output = []

    for x in values:
        divisors = divisor_cache.get(x)
        if divisors is None:
            z = x
            ds = [1]
            while z > 1:
                p = spf[z]
                exponent = 0
                while z % p == 0:
                    z //= p
                    exponent += 1
                old = ds.copy()
                power = 1
                for _ in range(exponent):
                    power *= p
                    ds.extend(d * power for d in old)
            divisors = tuple(ds)
            divisor_cache[x] = divisors

        # gcd(a, b) = sum_{d | a, d | b} phi(d).
        contribution = 0
        for d in divisors:
            contribution += phi[d] * weighted[d]

        answer = (2 * answer + contribution) % MOD
        output.append(str(answer))

        for d in divisors:
            updated = weighted[d] + position_weight
            if updated >= MOD:
                updated -= MOD
            weighted[d] = updated
        position_weight = position_weight * 2 % MOD

    sys.stdout.write('\n'.join(output))


if __name__ == '__main__':
    main()

