import sys
MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    N, M, K = data[:3]
    A = data[3:]

    # dp[(xor, length mod M)] is the number of subsets of the processed
    # prefix having that XOR and length residue.
    dp = {(0, 0): 1}
    for a in A:
        nxt = dp.copy()
        for (x, r), count in dp.items():
            key = (x ^ a, (r + 1) % M)
            nxt[key] = (nxt.get(key, 0) + count) % MOD
        dp = nxt

    ans = 0
    for (x, r), count in dp.items():
        if r == 0:
            ans = (ans + count * pow(x, K, MOD)) % MOD
    print(ans)

if __name__ == '__main__':
    main()

