from typing import List
import heapq
class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        ends=[[] for _ in range(n+1)]
        for i,(a,b) in enumerate(conflictingPairs):
            if a>b: a,b=b,a
            ends[b].append((a,i))
        h=[]
        base=0
        gain=[0]*len(conflictingPairs)
        for r in range(1,n+1):
            for a,i in ends[r]:
                heapq.heappush(h,(-a,i))
            if not h:
                base+=r
                continue
            first=heapq.heappop(h)
            top=-first[0]
            second=-h[0][0] if h else 0
            heapq.heappush(h,first)
            base+=r-top
            if top>second:
                gain[first[1]]+=top-second
