from typing import List
import heapq

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        ending = [[] for _ in range(n + 1)]
        for idx, (a, b) in enumerate(conflictingPairs):
            if a > b:
                a, b = b, a
            ending[b].append((a, idx))

        heap = []
        base = 0
        gains = [0] * len(conflictingPairs)

        for right in range(1, n + 1):
            for a, idx in ending[right]:
                heapq.heappush(heap, (-a, idx))

            if not heap:
                base += right
                continue

            first = heapq.heappop(heap)
            largest = -first[0]
            second_largest = -heap[0][0] if heap else 0
            heapq.heappush(heap, first)

            base += right - largest
            if largest > second_largest:
                gains[first[1]] += largest - second_largest

        return base + max(gains)

