import sys

def main():
    data=list(map(int,sys.stdin.buffer.read().split()))
    if not data:
        return
    it=iter(data)
    n=next(it); m=next(it); q=next(it)
    edges=[None]*m
    for i in range(m):
        a=next(it)-1
        b=next(it)-1
        c=next(it)
        edges[i]=(a,b,c)
    queries=[]
    closed=[False]*m
    for _ in range(q):
        t=next(it)
        if t==1:
            idx=next(it)-1
            queries.append((1,idx))
            closed[idx]=True
        else:
            x=next(it)-1
            y=next(it)-1
            queries.append((2,x,y))

    inf=10**30
    dist=[[inf]*n for _ in range(n)]
    for i in range(n):
        dist[i][i]=0
    for i,(a,b,c) in enumerate(edges):
        if not closed[i]:
            dist[a][b]=dist[b][a]=c

    # All-pairs shortest paths after every deletion has taken place.
    for k in range(n):
        dk=dist[k]
        for i in range(n):
            dik=dist[i][k]
            if dik==inf:
                continue
            di=dist[i]
            for j in range(n):
                candidate=dik+dk[j]
                if candidate<di[j]:
                    di[j]=candidate

    answers=[]
    for query in reversed(queries):
        if query[0]==2:
            _,x,y=query
            answers.append(str(dist[x][y] if dist[x][y]<inf else -1))
        else:
            _,idx=query
            a,b,c=edges[idx]
            # Insert the deleted undirected road. Any new shortest path uses
            # this road at most once, so it is described by old APSP distances.
            da=dist[a][:]
            db=dist[b][:]
            for i in range(n):
                di=dist[i]
                via_a=di[a]+c
                via_b=di[b]+c
                for j in range(n):
                    cand1=via_a+db[j]
                    cand2=via_b+da[j]
                    if cand1<di[j]:
                        di[j]=cand1
                    if cand2<di[j]:
                        di[j]=cand2
    print('\n'.join(reversed(answers)))

if __name__=='__main__':
    main()

