class Solution:
    def numberOfWays(self, n: int, x: int, y: int) -> int:
        dp=[0]*(x+1)
        dp[0]=1
        for i in range(1,n+1):
            ndp=[0]*(x+1)
            for k in range(1,min(i,x)+1):
                ndp[k]=(dp[k]*k + dp[k-1]*(x-k+1)*y)%MOD
