class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        n = len(s)

        # For a number with t set bits, one operation produces t. It is
        # reducible within k operations exactly when t reaches 1 within k-1.
        good = [False] * (n + 1)
        for t in range(1, n + 1):
            x, steps = t, 0
            while x != 1:
                x = x.bit_count()
                steps += 1
            good[t] = steps + 1 <= k

        # Pascal triangle modulo MOD.
        comb = [[0] * (n + 1) for _ in range(n + 1)]
        comb[0][0] = 1
        for i in range(1, n + 1):
            comb[i][0] = comb[i][i] = 1
            for j in range(1, i):
                comb[i][j] = (comb[i - 1][j - 1] + comb[i - 1][j]) % MOD

        # Scan the bound: at each 1, choose 0 here and freely choose the suffix.
        ans = 0
        ones = 0
        for i, bit in enumerate(s):
            if bit == '1':
                rem = n - i - 1
                for t in range(1, n + 1):
                    if good[t]:
                        need = t - ones
                        if 0 <= need <= rem:
                            ans += comb[rem][need]
                ones += 1
        return ans % MOD

