import sys
from collections import deque

def solve():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    n = int(data[0])
    graph = data[1:]
    full = (1 << n) - 1

    outgoing = [[[] for _ in range(26)] for _ in range(n)]
    incoming = [[[] for _ in range(26)] for _ in range(n)]
    out_mask = [[0] * 26 for _ in range(n)]
    for i, row in enumerate(graph):
        for j, ch in enumerate(row):
            if ch != ord('-'):
                c = ch - ord('a')
                outgoing[i][c].append(j)
                incoming[j][c].append(i)
                out_mask[i][c] |= 1 << j

    dist = [[-1] * n for _ in range(n)]
    unvisited = [full] * n
    queue = deque()

    # Empty paths and one-edge paths are the centers of palindromes.
    for i in range(n):
        dist[i][i] = 0
        unvisited[i] ^= 1 << i
        queue.append((i, i))
    for i in range(n):
        for c in range(26):
            for j in outgoing[i][c]:
                if dist[i][j] == -1:
                    dist[i][j] = 1
                    unvisited[i] ^= 1 << j
                    queue.append((i, j))

    incoming_by_vertex = [
        [(c, incoming[u][c]) for c in range(26) if incoming[u][c]]
        for u in range(n)
    ]

    while queue:
        u, v = queue.popleft()
        new_dist = dist[u][v] + 2
        for c, predecessors in incoming_by_vertex[u]:
            targets = out_mask[v][c]
            if not targets:
                continue
            for i in predecessors:
                bits = unvisited[i] & targets
                while bits:
                    bit = bits & -bits
                    bits -= bit
                    j = bit.bit_length() - 1
                    unvisited[i] ^= bit
                    dist[i][j] = new_dist
                    queue.append((i, j))

    sys.stdout.write('\n'.join(' '.join(map(str, row)) for row in dist))

solve()

