import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    rows = [0] * n
    p = 2
    for _ in range(m):
        u, v = data[p] - 1, data[p + 1] - 1
        p += 2
        rows[u] |= 1 << v
        rows[v] |= 1 << u

    # Reduced row echelon form over GF(2).
    rank = 0
    pivots = []
    for col in range(n):
        q = next((i for i in range(rank, n) if (rows[i] >> col) & 1), None)
        if q is None:
            continue
        rows[rank], rows[q] = rows[q], rows[rank]
        for i in range(n):
            if i != rank and ((rows[i] >> col) & 1):
                rows[i] ^= rows[rank]
        pivots.append(col)
        rank += 1

    pivot_set = set(pivots)
    free = [c for c in range(n) if c not in pivot_set]
    values = [0] * n
    for bit, f in enumerate(free):
        vec = 1 << f
        for i, c in enumerate(pivots):
            if (rows[i] >> f) & 1:
                vec |= 1 << c
        for v in range(n):
            if (vec >> v) & 1:
                values[v] |= 1 << bit

    if any(x == 0 for x in values):
        print('No')
        return
    # A common scaling preserves all XOR-zero equations; use it when in range.
    scale = 4 if n > 1 and max(values) <= ((1 << 60) - 1) // 4 else 1
    print('Yes')
    print(*(x * scale for x in values))

if __name__ == '__main__':
    main()

