N = int(input())

# Since N = (x-y)(x^2+xy+y^2) >= (x-y)^3,
# d = x-y cannot exceed floor(cuberoot(N)).
lo, hi = 0, 10**7
while lo < hi:
    mid = (lo + hi + 1) // 2
    if mid**3 <= N:
        lo = mid
    else:
        hi = mid - 1

for d in range(1, lo + 1):
    if N % d:
        continue
    q = N // d
    # 3y^2 + 3dy + d^2 = q
    disc = 12 * q - 3 * d * d
    if disc < 0:
        continue
    s = math.isqrt(disc)
    if s * s == disc and s > 3 * d and (s - 3 * d) % 6 == 0:
        y = (s - 3 * d) // 6
        if y > 0:
            print(y + d, y)
            break
else:
    print(-1)

