from typing import List
from array import array

class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n, m = len(grid), len(grid[0])
        # In matrix coordinates, clockwise turns cycle SE -> SW -> NW -> NE.
        dirs = [(1, 1), (1, -1), (-1, -1), (-1, 1)]
        size = n * m

        # S[d][p * size + cell]: longest straight valid run starting at cell,
        # with value p required there (p=0 means 0, p=1 means 2).
        S = [array('H', [0]) * (2 * size) for _ in range(4)]
        for d, (dr, dc) in enumerate(dirs):
            rows = range(n - 1, -1, -1) if dr == 1 else range(n)
            cols = range(m - 1, -1, -1) if dc == 1 else range(m)
            a = S[d]
            for r in rows:
                for c in cols:
                    v = grid[r][c]
                    if v not in (0, 2):
                        continue
                    p = 0 if v == 0 else 1
                    nr, nc = r + dr, c + dc
                    val = 1
                    if 0 <= nr < n and 0 <= nc < m:
                        val += a[(1 - p) * size + nr * m + nc]
                    a[p * size + r * m + c] = val

        # H allows at most one clockwise turn. It either continues in d,
        # retaining the turn, or turns now and follows a straight run.
        H = [array('H', [0]) * (2 * size) for _ in range(4)]
        for d, (dr, dc) in enumerate(dirs):
            cr, cc = dirs[(d + 1) % 4]
            rows = range(n - 1, -1, -1) if dr == 1 else range(n)
            cols = range(m - 1, -1, -1) if dc == 1 else range(m)
            a = H[d]
            turned_straight = S[(d + 1) % 4]
            for r in rows:
                for c in cols:
                    v = grid[r][c]
                    if v not in (0, 2):
                        continue
                    p = 0 if v == 0 else 1
                    best = 0
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < n and 0 <= nc < m:
                        best = a[(1 - p) * size + nr * m + nc]
                    nr, nc = r + cr, c + cc
                    if 0 <= nr < n and 0 <= nc < m:
                        best = max(best, turned_straight[(1 - p) * size + nr * m + nc])
                    a[p * size + r * m + c] = 1 + best

        answer = 0
        for r in range(n):
            for c in range(m):
                if grid[r][c] != 1:
                    continue
                answer = max(answer, 1)
                for d, (dr, dc) in enumerate(dirs):
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < n and 0 <= nc < m:
                        answer = max(answer, 1 + H[d][size + nr * m + nc])
        return answer

class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        m = (n + 1) // 2
        weights = []
        for i in range(m):
            if n % 2 and i == m - 1:
                # The center digit occurs only once.
                w = pow(10, i, k)
            else:
                # A mirrored pair contributes to two decimal positions.
                w = (pow(10, i, k) + pow(10, n - 1 - i, k)) % k
            weights.append(w)

        # can[i][r]: positions i..m-1 can contribute residue r modulo k.
        can = [bytearray(k) for _ in range(m + 1)]
        can[m][0] = 1
        for i in range(m - 1, -1, -1):
            nxt, cur, w = can[i + 1], can[i], weights[i]
            for r in range(k):
                for d in range(10):
                    if nxt[(r - d * w) % k]:
                        cur[r] = 1
                        break

        # Greedily choose each prefix digit, preserving a feasible completion.
        digits = []
        residue = 0
        for i, w in enumerate(weights):
            lowest = 1 if i == 0 else 0
            for d in range(9, lowest - 1, -1):
                new_residue = (residue + d * w) % k
                if can[i + 1][(-new_residue) % k]:
                    digits.append(str(d))
                    residue = new_residue
                    break

        half = ''.join(digits)
        return half + (half[:-1][::-1] if n % 2 else half[::-1])

