from typing import List

class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)
        prefix = [0] * (n + 1)
        for i, value in enumerate(nums):
            prefix[i + 1] = prefix[i] + value

        # next_greater[i] starts the next constant-prefix-maximum block.
        next_greater = [n] * n
        stack = []
        for i in range(n - 1, -1, -1):
            while stack and nums[stack[-1]] <= nums[i]:
                stack.pop()
            next_greater[i] = stack[-1] if stack else n
            stack.append(i)

        block_cost = [
            nums[i] * (next_greater[i] - i) - (prefix[next_greater[i]] - prefix[i])
            for i in range(n)
        ]

        levels = n.bit_length()
        jump = [next_greater]
        jump_cost = [block_cost]
        for _ in range(1, levels):
            prev_jump = jump[-1]
            prev_cost = jump_cost[-1]
            jump.append([
                prev_jump[prev_jump[i]] if prev_jump[i] < n else n
                for i in range(n)
            ])
            jump_cost.append([
                prev_cost[i] + (prev_cost[prev_jump[i]] if prev_jump[i] < n else 0)
                for i in range(n)
            ])

        answer = 0
        for start in range(n):
            node = start
            spent = 0
            # Consume all complete blocks that fit in the operation budget.
            for level in range(levels - 1, -1, -1):
                if node < n and spent + jump_cost[level][node] <= k:
                    spent += jump_cost[level][node]
                    node = jump[level][node]

            if node == n:
                end = n - 1
            else:
                # The remaining endpoint lies within this one block.
                lo, hi = node, next_greater[node] - 1
                remaining = k - spent
                while lo < hi:
                    mid = (lo + hi + 1) // 2
                    needed = nums[node] * (mid - node + 1) - (prefix[mid + 1] - prefix[node])
                    if needed <= remaining:
                        lo = mid
                    else:
                        hi = mid - 1
                end = lo

            answer += end - start + 1

        return answer

