class Solution:
    def makeStringGood(self, s: str) -> int:
        from collections import Counter
        counts = Counter(s)
        a = [counts[chr(97 + i)] for i in range(26)]
        answer = len(s)

        # For each possible common positive frequency, process the alphabet
        # from left to right. `carry` is the number of occurrences moved in
        # from the preceding letter. `out` is how many are moved to the next.
        for target in range(1, max(a) + 1):
            dp = {0: 0}
            for original in a:
                ndp = {}
                for carry, old_cost in dp.items():
                    available = original + carry
                    for final_count in (0, target):
                        for out in range(available + 1):
                            cost = old_cost + out + abs(available - out - final_count)
                            if cost < ndp.get(out, 10**9):
                                ndp[out] = cost
                dp = ndp
            answer = min(answer, min(dp.values()))
        return answer

