class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        from bisect import bisect_left, bisect_right

        n = len(s)
        first = p.index('*')
        second = p.rindex('*')
        a_text, b_text, c_text = p[:first], p[first + 1:second], p[second + 1:]

        def occurrences(t):
            if not t:
                return list(range(n + 1))

            # KMP prefix-function
            pi = [0] * len(t)
            for i in range(1, len(t)):
                j = pi[i - 1]
                while j and t[i] != t[j]:
                    j = pi[j - 1]
                if t[i] == t[j]:
                    j += 1
                pi[i] = j

            result = []
            j = 0
            for i, ch in enumerate(s):
                while j and ch != t[j]:
                    j = pi[j - 1]
                if ch == t[j]:
                    j += 1
                if j == len(t):
                    result.append(i - len(t) + 1)
                    j = pi[j - 1]
            return result

        a_occ = occurrences(a_text)
        b_occ = occurrences(b_text)
        c_occ = occurrences(c_text)
        len_a, len_b, len_c = len(a_text), len(b_text), len(c_text)

        best = n + 1
        for b_start in b_occ:
            # Select the latest A occurrence ending at or before B starts.
            a_index = bisect_right(a_occ, b_start - len_a) - 1
            if a_index < 0:
                continue

            b_end = b_start + len_b
            c_index = bisect_left(c_occ, b_end)
            if c_index == len(c_occ):
                continue

            best = min(best, c_occ[c_index] + len_c - a_occ[a_index])

        return -1 if best == n + 1 else best

