from typing import List

class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        children = [[] for _ in range(n)]
        for i in range(1, n):
            children[parent[i]].append(i)

        postorder = []
        sizes = [0] * n
        starts = [0] * n
        stack = [(0, False)]
        while stack:
            x, exiting = stack.pop()
            if not exiting:
                stack.append((x, True))
                for y in reversed(children[x]):
                    stack.append((y, False))
            else:
                sizes[x] = 1 + sum(sizes[y] for y in children[x])
                # The descendants have already been appended; x is appended next.
                starts[x] = len(postorder) - sizes[x] + 1
                postorder.append(s[x])

        text = ''.join(postorder)
        m = len(text)

        # Odd palindrome radii: d1[i] includes the center character.
        d1 = [0] * m
        left, right = 0, -1
        for i in range(m):
            radius = 1 if i > right else min(d1[left + right - i], right - i + 1)
            while i - radius >= 0 and i + radius < m and text[i - radius] == text[i + radius]:
                radius += 1
            d1[i] = radius
            if i + radius - 1 > right:
                left, right = i - radius + 1, i + radius - 1

        # Even palindrome radii: d2[i] is centered between i-1 and i.
        d2 = [0] * m
        left, right = 0, -1
        for i in range(m):
            radius = 0 if i > right else min(d2[left + right - i + 1], right - i + 1)
            while i - radius - 1 >= 0 and i + radius < m and text[i - radius - 1] == text[i + radius]:
                radius += 1
            d2[i] = radius
            if i + radius - 1 > right:
                left, right = i - radius, i + radius - 1

        answer = [False] * n
        for x in range(n):
            length = sizes[x]
            start = starts[x]
            if length & 1:
                answer[x] = d1[start + length // 2] >= length // 2 + 1
            else:
                answer[x] = d2[start + length // 2] >= length // 2
        return answer

