class Solution:
    def maxEnergyBoost(self, energyDrinkA: List[int], energyDrinkB: List[int]) -> int:
        n = len(energyDrinkA)
        dp_a = [0] * n
        dp_b = [0] * n
        dp_a[0] = energyDrinkA[0]
        dp_b[0] = energyDrinkB[0]

        for i in range(1, n):
            if i == 1:
                # A switch requires a cleansing hour, so it cannot happen yet.
                dp_a[i] = dp_a[i - 1] + energyDrinkA[i]
                dp_b[i] = dp_b[i - 1] + energyDrinkB[i]
            else:
                dp_a[i] = energyDrinkA[i] + max(dp_a[i - 1], dp_b[i - 2])
                dp_b[i] = energyDrinkB[i] + max(dp_b[i - 1], dp_a[i - 2])

