class Solution:
    def countPairs(self, nums: List[int]) -> int:
        def reachable_by_one_swap(value: int) -> set[int]:
            digits = list(str(value))
            reachable = {value}
            for i in range(len(digits)):
                for j in range(i + 1, len(digits)):
                    digits[i], digits[j] = digits[j], digits[i]
                    # int() correctly handles leading zeros created by a swap.
                    reachable.add(int(''.join(digits)))
                    digits[i], digits[j] = digits[j], digits[i]
            return reachable

        reachable = {value: reachable_by_one_swap(value) for value in set(nums)}
        pairs = 0
        for i in range(len(nums)):
            for j in range(i + 1, len(nums)):
                x, y = nums[i], nums[j]
                # Exactly one value may be changed (or neither), so one original
                # value must be reachable from the other by at most one swap.
                if x in reachable[y] or y in reachable[x]:
                    pairs += 1
        return pairs

