class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        n = len(nums)
        reachable = [1] * n  # Bit s is set when sum s is attainable.
        masks = [(1 << (x + 1)) - 1 for x in nums]
        done = [x == 0 for x in nums]

        if all(done):
            return 0

        for k, (left, right, val) in enumerate(queries, 1):
            for i in range(left, right + 1):
                if not done[i]:
                    reachable[i] = (reachable[i] | (reachable[i] << val)) & masks[i]
                    if (reachable[i] >> nums[i]) & 1:
                        done[i] = True
            if all(done):
                return k

