import heapq

class Solution:
    def minOperations(self, n: int, m: int) -> int:
        def is_prime(x: int) -> bool:
            if x < 2:
                return False
            if x % 2 == 0:
                return x == 2
            k = 3
            while k * k <= x:
                if x % k == 0:
                    return False
                k += 2
            return True

        if is_prime(n) or is_prime(m):
            return -1
        if n == m:
            return n

        digits = len(str(n))
        lower = 0 if digits == 1 else 10 ** (digits - 1)
        upper = 10 ** digits - 1
        dist = {n: n}
        heap = [(n, n)]

        while heap:
            cost, value = heapq.heappop(heap)
            if cost != dist.get(value):
                continue
            if value == m:
                return cost

            chars = list(str(value))
            for i, char in enumerate(chars):
                digit = int(char)
                for delta in (-1, 1):
                    new_digit = digit + delta
                    if not 0 <= new_digit <= 9:
                        continue
                    if i == 0 and digits > 1 and new_digit == 0:
                        continue
                    next_value = value + delta * (10 ** (digits - 1 - i))
                    if not lower <= next_value <= upper or is_prime(next_value):
                        continue
                    next_cost = cost + next_value
                    if next_cost < dist.get(next_value, float('inf')):
                        dist[next_value] = next_cost
                        heapq.heappush(heap, (next_cost, next_value))

        return -1

