from typing import List

class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)
        if n < 3:
            return 0

        def zfunc(a):
            m = len(a)
            z = [0] * m
            left = right = 0
            for k in range(1, m):
                if k < right:
                    v = z[k - left]
                    if v > right - k:
                        v = right - k
                    z[k] = v
                while k + z[k] < m and a[z[k]] == a[k + z[k]]:
                    z[k] += 1
                if k + z[k] > right:
                    left, right = k, k + z[k]
            return z

        prefix_z = zfunc(nums)
        answer = 0

        for i in range(1, n - 1):
            first_condition = prefix_z[i] >= i
            if first_condition:
                # For nums1 to be a prefix of nums2, nums2 must be at least i long.
                answer += max(0, n - 2 * i)

            # For each length d, test whether nums2 is a prefix of nums3.
            suffix_z = zfunc(nums[i:])
            for d in range(1, (n - i) // 2 + 1):
                if (not first_condition or d < i) and suffix_z[d] >= d:
                    answer += 1

        return answer

