class Solution:
    def maxRemovals(self, source: str, pattern: str, targetIndices: List[int]) -> int:
        m = len(pattern)
        neg = -10**9
        dp = [neg] * (m + 1)
        dp[0] = 0
        targets = set(targetIndices)

        for i, ch in enumerate(source):
            # Retain the character without using it for the subsequence.
            ndp = dp[:]

            # Remove it if its index is allowed.
            if i in targets:
                for j, value in enumerate(dp):
                    if value != neg and value + 1 > ndp[j]:
                        ndp[j] = value + 1

            # Retain it and use it to match the next pattern character.
            for j in range(m):
                if ch == pattern[j] and dp[j] > ndp[j + 1]:
                    ndp[j + 1] = dp[j]
            dp = ndp

        return dp[m]

