class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        # A state records the colors of a symmetric pair: (left, right).
        states = [(a, b) for a in range(3) for b in range(3) if a != b]
        inf = 10**30

        dp = [cost[0][a] + cost[n - 1][b] for a, b in states]

        # Process symmetric pairs from the outside toward the center.
        for i in range(1, n // 2):
            ndp = [inf] * 6
            for cur, (a, b) in enumerate(states):
                pair_cost = cost[i][a] + cost[n - 1 - i][b]
                for prev, (pa, pb) in enumerate(states):
                    # Adjacent houses on both sides must have different colors.
                    if pa != a and pb != b:
                        ndp[cur] = min(ndp[cur], dp[prev] + pair_cost)
            dp = ndp

        return min(dp)

