class Solution:
    def maxActiveSectionsAfterTrade(self, s: str) -> int:
        t = '1' + s + '1'
        runs = []
        i = 0
        while i < len(t):
            j = i + 1
            while j < len(t) and t[j] == t[i]:
                j += 1
            runs.append((t[i], j - i))
            i = j

        best_gain = 0
        # A trade centers on an interior run of ones. Flipping it to zero
        # joins the zero runs on either side; flipping that joined block
        # to one gains exactly the lengths of those two zero runs.
        for k in range(2, len(runs) - 2):
            if runs[k][0] == '1':
                best_gain = max(best_gain, runs[k - 1][1] + runs[k + 1][1])

        return s.count('1') + best_gain

